     .message {
       min-height: 1.25rem;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .message.success {
       color: #166534;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Notification settings</h1>
     <p>Choose the single channel you prefer for receiving product updates.</p>

     <form id="notification-form">
       <div class="form-field">
         <div class="question" id="notification-question">
           How do you prefer to receive notifications?
         </div>
         <div class="options" role="radiogroup" aria-labelledby="notification-question">
           <label class="option">
             <input type="radio" name="notification" id="email" value="Email" required />
             <span>Email</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" id="sms" value="SMS" />
             <span>SMS</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" id="push" value="Push Notifications" />
             <span>Push Notifications</span>
           </label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit</button>
         <div class="message" id="form-message" aria-live="polite"></div>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('notification-form');
     const message = document.getElementById('form-message');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selected = form.querySelector('input[name="notification"]:checked');
       if (!selected) {
         message.textContent = 'Please choose one notification method.';
         message.className = 'message';
         return;
       }

       message.textContent = `Saved preference: ${selected.value}.`;
       message.className = 'message success';
     });
   </script>
 </body>
 </html>

')
